DO $test$
DECLARE u uuid;bid uuid:=gen_random_uuid();other_bid uuid:=gen_random_uuid();plan uuid;inv uuid:=gen_random_uuid();exp uuid:=gen_random_uuid();pay uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();sheet uuid:=gen_random_uuid();r jsonb;r2 jsonb;denied boolean;rows_before bigint;accounts_before bigint;
BEGIN
 IF public.frindly_market_environment_status()->>'project_ref' IS DISTINCT FROM 'smvvevrtjqkflyqkyape' THEN RAISE EXCEPTION 'Market only';END IF;
 SELECT id INTO u FROM auth.users a WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id) ORDER BY id LIMIT 1;
 SELECT id INTO plan FROM public.plans ORDER BY cardinality(included_modules) DESC NULLS LAST LIMIT 1;
 IF u IS NULL OR plan IS NULL THEN RAISE EXCEPTION 'Fixture prerequisites missing';END IF;
 BEGIN
  INSERT INTO public.businesses(id,name,settings) VALUES(bid,'Market conversion evidence fixture','{"country":"NZ","currency":"NZD"}'),(other_bid,'Market conversion foreign fixture','{"country":"NZ","currency":"NZD"}');
  INSERT INTO public.profiles(id,business_id,active_business_id,role,is_super_admin) VALUES(u,bid,bid,'owner',false);
  INSERT INTO public.business_memberships(business_id,user_id,role,status) VALUES(bid,u,'owner','active');
  INSERT INTO public.subscriptions(business_id,plan_id,status,current_period_end,trial_ends_at) VALUES(bid,plan,'trialing',now()+interval '30 days',now()+interval '30 days');
  INSERT INTO public.accounting_periods(business_id,period_start,period_end,financial_year,status) VALUES(bid,'2026-04-01','2027-03-31',2027,'open');
  PERFORM set_config('request.jwt.claim.sub',u::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
  INSERT INTO public.invoices(id,business_id,invoice_number,invoice_date,customer_name,subtotal,gst,total,balance_due,company_snapshot,lifecycle_state,lifecycle_version) VALUES(inv,bid,'CONVERSION-322','2026-09-30','Fixture',280,42,322,322,'{"currency":"NZD"}',NULL,NULL);
  INSERT INTO public.customer_payments(id,business_id,invoice_id,payment_date,amount) VALUES(pay,bid,inv,'2026-10-01',161),(gen_random_uuid(),bid,inv,'2026-10-15',161);
  INSERT INTO public.expenses(id,business_id,expense_number,supplier_name,invoice_date,ex_gst,gst_amount,total_amount,currency,payment_status) VALUES(exp,bid,'CONVERSION-115','Fixture supplier','2026-09-30',100,15,115,'NZD','unpaid');
  INSERT INTO public.expense_payments(business_id,expense_id,payment_date,amount) VALUES(bid,exp,'2026-10-02',50),(bid,exp,'2026-10-20',25);
  INSERT INTO public.import_batches(id,business_id,user_id,filename,source_type,file_sha256,status,cutover_date) VALUES(batch,bid,u,'conversion.csv','csv',batch::text,'analysed','2026-10-10');
  INSERT INTO public.import_sheets(id,batch_id,business_id,sheet_index,sheet_name,detected_record_type,headers,sample_rows,row_count) VALUES(sheet,batch,bid,0,'Invoices','invoices','[]','[]',1);
  INSERT INTO public.import_records(batch_id,sheet_id,business_id,record_type,group_key,canonical_hash,display_label,normalized_data,commit_mode) VALUES(batch,sheet,bid,'invoices',inv::text,inv::text,'Historical partial',jsonb_build_object('date','2026-09-30','total',322,'paid_amount',161,'outstanding_amount',161,'currency','NZD'),'historical_reference');
  UPDATE public.import_batches SET status='completed' WHERE id=batch;
  SELECT count(*) INTO rows_before FROM public.accounting_journals WHERE business_id=bid;
  SELECT count(*) INTO accounts_before FROM public.accounting_accounts WHERE business_id=bid;
  EXECUTE 'SET LOCAL ROLE authenticated';
  r:=public.v6228_starting_balance_evidence('2026-10-10');r2:=public.v6228_starting_balance_evidence('2026-10-10');
  IF r->>'business_id'<>bid::text OR r->>'ledger_as_of'<>'2026-10-09' OR r->>'posts_balances'<>'false' OR r->>'snapshot_hash' IS DISTINCT FROM r2->>'snapshot_hash' OR jsonb_array_length(r->'documents')<>2 OR jsonb_array_length(r->'completed_imports')<>1 THEN RAISE EXCEPTION 'Conversion evidence incomplete or unstable';END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'documents')d WHERE d->>'id'=inv::text AND (d->>'paid_before')::numeric=161 AND (d->>'paid_all')::numeric=322 AND (d->>'stored_paid')::numeric=322 AND (d->>'open_before_cutover')::numeric=161) THEN RAISE EXCEPTION 'Later customer payment was included at cutover';END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'documents')d WHERE d->>'id'=exp::text AND (d->>'paid_before')::numeric=50 AND (d->>'paid_all')::numeric=75 AND (d->>'open_before_cutover')::numeric=65) THEN RAISE EXCEPTION 'Later supplier payment was included at cutover';END IF;
  IF (SELECT count(*) FROM public.accounting_journals WHERE business_id=bid)<>rows_before OR (SELECT count(*) FROM public.accounting_accounts WHERE business_id=bid)<>accounts_before THEN RAISE EXCEPTION 'Review wrote accounting data';END IF;
  denied:=false;BEGIN PERFORM public.v6228_starting_balance_evidence('infinity');EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Invalid starting date accepted';END IF;
  EXECUTE 'RESET ROLE';UPDATE public.customer_payments SET amount=160 WHERE id=pay;
  EXECUTE 'SET LOCAL ROLE authenticated';r2:=public.v6228_starting_balance_evidence('2026-10-10');IF r->>'snapshot_hash'=r2->>'snapshot_hash' THEN RAISE EXCEPTION 'Changed settlement evidence kept the same fingerprint';END IF;
  EXECUTE 'RESET ROLE';
  INSERT INTO public.invoices(id,business_id,invoice_number,invoice_date,customer_name,subtotal,gst,total,balance_due,company_snapshot,lifecycle_state,lifecycle_version) VALUES(gen_random_uuid(),bid,'FUTURE-PREPAY','2026-10-20','Prepayment',100,15,115,115,'{"currency":"NZD"}',NULL,NULL) RETURNING id INTO inv;
  INSERT INTO public.customer_payments(business_id,invoice_id,payment_date,amount,is_legacy_estimate) VALUES(bid,inv,'2026-10-05',20,true);
  EXECUTE 'SET LOCAL ROLE authenticated';r2:=public.v6228_starting_balance_evidence('2026-10-10');
  IF (r2->'counts'->>'documents')::int<>3 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r2->'documents')d WHERE d->>'reference'='FUTURE-PREPAY' AND (d->>'paid_before')::numeric=20 AND (d->>'estimated_payments')::int=1 AND (d->>'open_before_cutover')::numeric=0 AND (d->>'excess_credit')::numeric=20) THEN RAISE EXCEPTION 'Future-invoice prepayment or estimated-payment evidence omitted';END IF;
  PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
  denied:=false;BEGIN PERFORM public.v6228_starting_balance_evidence('2026-10-10');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign caller read conversion evidence';END IF;
  PERFORM set_config('request.jwt.claim.sub',u::text,true);EXECUTE 'RESET ROLE';
  UPDATE public.business_memberships SET role='viewer' WHERE business_id=bid AND user_id=u;
  EXECUTE 'SET LOCAL ROLE authenticated';denied:=false;BEGIN PERFORM public.v6228_starting_balance_evidence('2026-10-10');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Read-only caller accessed conversion workflow';END IF;
  EXECUTE 'RESET ROLE';
  IF has_function_privilege('anon','public.v6228_starting_balance_evidence(date)','EXECUTE') THEN RAISE EXCEPTION 'Anonymous conversion evidence access';END IF;
  RAISE EXCEPTION USING ERRCODE='P6228',MESSAGE='Rollback conversion evidence fixtures';
 EXCEPTION WHEN SQLSTATE 'P6228' THEN NULL;END;
 IF EXISTS(SELECT 1 FROM public.businesses WHERE id IN (bid,other_bid)) THEN RAISE EXCEPTION 'Conversion fixture leaked';END IF;
 RAISE NOTICE 'Conversion evidence fixture passed; all data rolled back';
END;$test$;
